def encode(message):
    vowels = 'aeiou'
    result = ''
    for char in message:
        if char.lower() in vowels:
            index = vowels.index(char.lower())
            result += chr(ord('a') + (index + 2) % 5) if char.islower() else chr(ord('A') + (index + 2) % 5)
        else:
            result += char.swapcase()
    return result
